.upsell-body { display: flex; flex-direction: column; gap: 2px; line-height: 1.4; }
.upsell-kicker { font-size: 12px; font-weight: 700; color: #2e6f9e; }
.upsell-price { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; }
.upsell-price .price { font-size: 18px; }
.trust-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; width: 100%; padding-top: 20px; border-top: 1px solid var(--border); }
.trust-grid li { display: flex; align-items: flex-start; gap: 10px; font-size: 13px; color: var(--muted); line-height: 1.4; }
.trust-grid .ic { color: var(--navy); margin-top: 1px; }
.trust-grid strong { display: block; font-size: 14px; color: var(--navy); }
.benefit-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 16px; }
.benefit { display: flex; flex-direction: column; gap: 8px; padding: 24px 20px; background: #fff; border-radius: var(--r-lg); border: 1px solid var(--border); }
.benefit .ic { color: var(--navy); margin-bottom: 8px; }
.benefit-title { font-size: 16px; font-weight: 700; line-height: 1.35; }
.benefit p { font-size: 14px; color: var(--muted); line-height: 1.5; }
.tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--border); margin-bottom: 32px; overflow-x: auto; scrollbar-width: none; }
.tabs::-webkit-scrollbar { display: none; }
.tab { position: relative; height: 52px; padding: 0 18px; font-size: 16px; font-weight: 600; color: var(--muted); white-space: nowrap; border-radius: var(--r-md) var(--r-md) 0 0; }
.tab:hover { color: var(--navy); background: var(--page); }
.tab.is-active { color: var(--navy); }
.tab.is-active::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 3px; border-radius: 2px; background: var(--yellow); }
.tab-split { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 56px; align-items: start; }
.prose { display: grid; gap: 16px; max-width: 720px; }
.prose p { color: var(--muted); line-height: 1.7; }
.prose-lg p { font-size: 17px; }
.spec-card { padding: 24px; background: var(--page); border-radius: var(--r-lg); }
.spec-title { font-size: 17px; font-weight: 700; margin-bottom: 12px; }
.specs { display: grid; }
.spec { display: flex; justify-content: space-between; gap: 16px; padding: 11px 0; border-bottom: 1px solid var(--border); font-size: 14px; }
.spec:last-child { border-bottom: 0; }
.spec dt { color: var(--muted); }
.spec dd { font-weight: 600; text-align: right; }
.toc { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 48px; margin-top: 16px; }
.toc li { display: flex; align-items: baseline; gap: 12px; padding: 12px 0; border-bottom: 1px solid var(--border); }
.toc-n { display: inline-grid; place-items: center; width: 28px; height: 28px; border-radius: var(--r-sm); background: var(--panel); font-size: 13px; font-weight: 700; flex: none; align-self: center; }
.toc-title { font-weight: 500; }
.toc-dots { flex: 1; border-bottom: 1.5px dotted var(--control); transform: translateY(-4px); min-width: 16px; }
.toc-page { font-size: 14px; color: var(--muted); font-weight: 600; white-space: nowrap; }
.sticky-bar { display: none; }

/* ---------- Online oefenen ---------- */
.hero-online .breadcrumb ol, .hero-about .breadcrumb ol { margin-bottom: 24px; }
.hero-online .hero-copy .t-display { font-size: calc(var(--h-display) - 2px); }
.quiz { display: flex; flex-direction: column; gap: 14px; padding: 20px; border-radius: 12px; background: #fff; border: 1px solid var(--border); box-shadow: 0 30px 60px -40px rgba(11, 37, 69, .5); }
.quiz-head { display: flex; align-items: center; gap: 12px; }
.quiz-timer { margin-left: auto; display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; padding: 4px 10px; border-radius: var(--r-sm); background: var(--page); }
.quiz-progress { height: 6px; border-radius: 3px; background: var(--panel); overflow: hidden; }
.quiz-progress i { display: block; width: var(--w); height: 100%; background: var(--sky); }
.quiz-scene { width: 100%; height: auto; border-radius: var(--r-lg); }
.quiz-q { font-size: 18px; font-weight: 700; }
.quiz-options { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.quiz-opt { display: flex; align-items: center; justify-content: center; gap: 6px; height: 48px; padding: 0 8px; border-radius: var(--r-md); border: 1.5px solid var(--border); font-weight: 600; font-size: 15px; text-align: center; }
.quiz-opt.is-picked { border-color: var(--navy); background: var(--navy); color: #fff; }
.quiz-feedback { display: flex; gap: 12px; padding: 14px; border-radius: var(--r-md); background: var(--panel); font-size: 14px; line-height: 1.5; }
.quiz-feedback strong { display: block; }
.dash-showcase { max-width: 1080px; margin: 0 auto; }
.dash-showcase .dash { font-size: 14px; }
.callouts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; max-width: 1080px; margin: 24px auto 0; }
.callouts li { display: flex; gap: 14px; align-items: flex-start; padding: 20px; background: #fff; border-radius: var(--r-lg); border: 1px solid var(--border); }
.callout-num { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: var(--navy); color: #fff; font-weight: 700; font-size: 14px; flex: none; }
.callout-title { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
.feature-card { display: flex; flex-direction: column; gap: 10px; padding: 28px; background: #fff; border: 1px solid var(--border); border-radius: var(--r-lg); transition: border-color .15s; }
.feature-card:hover { border-color: var(--sky-light); }
.feature-card .t-h3 { font-size: 19px; margin-top: 8px; }
.feature-card p { color: var(--muted); font-size: 15px; }
.segmented { display: flex; width: max-content; margin: 0 auto 32px; padding: 4px; gap: 4px; border-radius: var(--r-lg); background: #fff; border: 1px solid var(--border); }
.seg { height: 44px; padding: 0 22px; border-radius: var(--r-md); font-weight: 700; font-size: 15px; color: var(--muted); }
.seg:hover { color: var(--navy); background: var(--page); }
.seg.is-active { background: var(--navy); color: #fff; }
.plan-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; align-items: stretch; max-width: 1120px; margin: 0 auto; }
.plan { display: flex; flex-direction: column; gap: 8px; padding: 28px; background: #fff; border: 1px solid var(--border); border-radius: var(--r-lg); }
.plan-featured { border: 2px solid var(--navy); position: relative; }
.plan-badge-slot { min-height: 24px; }
.plan-name { font-size: 22px; font-weight: 700; }
.plan-desc { color: var(--muted); font-size: 15px; min-height: 48px; }
.plan-price { display: flex; align-items: baseline; gap: 10px; margin-top: 8px; }
.plan-per { font-size: 13px; color: var(--muted); }
.plan-features { display: grid; gap: 10px; margin: 20px 0 28px; padding-top: 20px; border-top: 1px solid var(--border); }
.plan-features li { display: flex; align-items: flex-start; gap: 10px; font-size: 15px; }
.plan-features .ic { color: var(--navy); margin-top: 2px; }
.plan-features .is-off { color: var(--muted); }
.plan-features .is-off .ic { color: var(--control); }
.plan .btn { margin-top: auto; }
.plans-note { display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 24px; font-size: 14px; color: var(--muted); text-align: center; }
.topic-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; }
.topic { display: flex; align-items: center; gap: 16px; padding: 20px; background: #fff; border: 1px solid var(--border); border-radius: var(--r-lg); }
.topic-ic { display: grid; place-items: center; width: 56px; height: 56px; border-radius: var(--r-lg); background: var(--panel); color: var(--navy); flex: none; }
.topic-title { font-size: 16px; font-weight: 700; line-height: 1.3; }

